def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    rows={}
    for r,c in pts: rows.setdefault(r,[]).append(c)
    # The row containing multiple markers is the main horizontal trunk.
    trunk=max(rows, key=lambda r: len(rows[r]))
    cs=rows[trunk]
    for c in range(min(cs),max(cs)+1):
        if out[trunk][c]==0: out[trunk][c]=3
    # Connect each remaining marker straight vertically to the trunk.
    for r,c in pts:
        if r!=trunk:
            for rr in range(min(r,trunk)+1,max(r,trunk)):
                if out[rr][c]==0: out[rr][c]=3
    return out
